function ruleExplanation(){const signs=(scene.geometry.cleanSigns||[]).map(s=>s.kind),answer=scene.options.find(o=>o.id===correctOrder())?.text||'a megjelölt sorrend';let rule;if(scene.oneWayTurn)rule='Egyirányú forgalmú útról balra bekanyarodás előtt — eltérő útburkolati jel hiányában — az úttest bal szélére kell besorolni (KRESZ 31. §).';else if(scene.topic==='bus')rule=scene.busArea==='inside'?'Lakott területen a menetrend szerint közlekedő autóbusz megállóhelyről való elindulását — hirtelen fékezés nélkül — lassítással, szükség esetén megállással lehetővé kell tenni. Az autóbusz vezetője csak akkor indulhat el, ha meggyőződött annak veszélytelenségéről.':'Lakott területen kívül az autóbuszt nem illeti meg a megállóhelyről elindulás külön elsőbbsége, ezért elsőbbséget kell adnia a forgalmi sávban már haladó járműnek.';else if(scene.topic==='turning-priority')rule='A kiegészítő tábla vastag vonala mutatja a főútvonal kanyarodó vonalvezetését. A főútvonalról letérő járműnek elsőbbséget kell adnia a főútvonalon továbbhaladó jármű részére (KRESZ 31. § (8)).';else if(scene.topic==='pedestrian')rule='A jobbra vagy balra bekanyarodó járműnek elsőbbséget kell adnia annak a gyalogosnak, aki azon az úttesten halad át, amelyre a jármű bekanyarodik. Kijelölt gyalogos-átkelőhelyen a gyalogos elsőbbségét szintén biztosítani kell (KRESZ 31. § (5) és 43. §).';else if(scene.topic==='bicycle')rule='A kanyarodó járműnek elsőbbséget kell adnia az általa keresztezett kerékpársávon, kerékpárúton vagy gyalog- és kerékpárúton szabályosan érkező kerékpáros részére; az elsőbbségi viszonyt az adott helyen levő táblákkal és útburkolati jelekkel együtt kell értékelni (KRESZ 31. § (5)).';else if(scene.topic==='tram')rule='Egyenrangú útkereszteződésben elsőbbséget kell adni a jobbról érkező minden járműnek és a balról érkező villamosnak. A bekanyarodó villamosra és járműre a kanyarodási szabályokat is alkalmazni kell (KRESZ 28. § és 31. §).';else if(scene.topic==='narrow')rule='Útszűkületben a kihelyezett elsőbbségi jelzőtáblák határozzák meg, melyik irány haladhat először; táblák hiányában az akadály helyzetét és a már megkezdett áthaladást kell figyelembe venni.';else if(scene.topic==='equal')rule='Egyenrangú útkereszteződésben elsőbbséget kell adni a jobbról érkező minden járműnek. Ha valamelyik résztvevő balra kanyarodik, a szemből egyenesen továbbhaladó vagy jobbra kanyarodó járműnek is elsőbbséget ad (KRESZ 28. § és 31. §).';else if(signs.includes('stop'))rule='Az „ÁLLJ! Elsőbbségadás kötelező” tábla felől érkezőnek meg kell állnia, majd elsőbbséget kell adnia a keresztező, illetve a kiegészítő táblán vastag vonallal jelzett útról érkezőknek (KRESZ 28. §).';else if(signs.includes('yield'))rule='Az „Elsőbbségadás kötelező” tábla felől érkezőnek elsőbbséget kell adnia a keresztező, illetve a kiegészítő táblán vastag vonallal jelzett útról érkezőknek (KRESZ 28. §).';else if(signs.includes('priority'))rule='A főútvonalon közlekedő jármű elsőbbséget élvez az alárendelt útról érkezővel szemben; az azonos rangú résztvevők között a kanyarodási szabály dönt.';else rule='A sorrendet az adott útkereszteződés jelzőtáblái, útburkolati jelei és a résztvevők haladási iránya határozza meg.';return(scene.oneWayTurn?'Helyes válasz: ':'Helyes sorrend: ')+answer+'. '+rule}
function showRuleExplanation(){const box=$('#rule-explanation');$('#rule-text').textContent=ruleExplanation();box.hidden=false;box.open=true}
function choose(v,solution=false,forcedWrong=false,collision=false){if(practice.active&&practice.answered)return;variant=v;frame=0;total=scene.sprites[scene.variants[v].id].frames;playing=true;last=0;awaitingStageChoice=false;stageAnimating=false;collisionMode=collision;collisionShown=false;collisionHappens=false;const correct=v===scene.correct&&!forcedWrong;pendingAutoAdvance=correct&&!solution;if(practice.active){const scoredCorrect=correct&&!solution;practice.answered=true;practice[scoredCorrect?'correct':'wrong']++;document.querySelectorAll('[data-variant]').forEach(b=>b.disabled=true);$('#solution').disabled=true;$('#feedback').className='feedback '+(scoredCorrect?'good':'bad');$('#feedback').textContent=scoredCorrect?'Helyes! Elindul a helyes áthaladási sorrend, majd következik a következő feladat.':forcedWrong?'Rossz döntés – figyeld meg, miért következne be ütközés.':solution?'A megoldást megnézted, ezért ez a kérdés hibás válasznak számít.':'Hibás válasz. Figyeld meg a helyes sorrendet, majd lépj tovább.';updatePracticePanel()}else{$('#feedback').className='feedback '+(correct?'good':'bad');$('#feedback').textContent=forcedWrong?'Rossz döntés – az animáció megmutatja a lehetséges ütközést.':solution?'A helyes áthaladási sorrend animációja.':correct?'Helyes! Elindul a helyes áthaladási sorrend, majd következik a következő feladat.':'Ez a sorrend hibás. Nézd meg a mozgást, majd próbáld újra.'}showRuleExplanation();controls();draw()}
function reset(){clearTimeout(autoAdvanceTimer);pendingAutoAdvance=false;variant=null;frame=0;total=1;playing=false;last=0;collisionMode=false;collisionShown=false;collisionHappens=false;collisionClosestDistance=Infinity;collisionPair=[];collisionVariants=[];collisionBaseState=[];collisionPathStarts=[];collisionRoutePaths=[];collisionActorFrames=[1,1];collisionStopFrame=1;stagePauseFrame=0;stageAnimating=false;awaitingStageChoice=false;stageFrozenState=[];stageMovingLabels=[];stageSourceStart=0;stagePathStarts=new Map();stageRoutePaths=new Map();stageFinal=false;queuedFinalStage=[];clickStages=[];clickCandidates=scene.options.slice();$('#solution').disabled=false;$('#feedback').className='feedback';$('#feedback').textContent=scene.oneWayTurn?'Válaszd ki, szabályos-e a besorolás.':'Kattints a képen arra, aki szerinted először haladhat.';$('#rule-explanation').hidden=true;$('#rule-explanation').open=false;if(scene.oneWayTurn){$('#answers').innerHTML=shuffle(scene.options).map((o,i)=>'<button data-variant="'+o.id+'"><span class="ordinal">'+(i+1)+'</span><span class="answertext">'+o.text+'</span></button>').join('');document.querySelectorAll('[data-variant]').forEach(b=>b.onclick=()=>choose(b.dataset.variant))}else $('#answers').innerHTML=clickAnswerMarkup();controls();draw()}
function select(n){scene=data.find(s=>s.number===n);if(!scene)return;current=n;snapshots.clear();$('#modern-drawing').removeAttribute('transform');$('#modern-drawing').innerHTML=background()+'<g id="intentions" transform="translate(-290 0)" opacity=".95">'+intentions(scene.initial)+'</g><g id="modern-actors"></g>';modernizeArrows();const shown=displayNumber(n);$('#position').textContent=String(shown).padStart(3,'0');$('#scene-label').innerHTML=String(shown).padStart(3,'0')+' <span>FORGALMI HELYZET</span>';$('#task-meta').textContent=scene.oneWayTurn?scene.options.length+' válaszlehetőség':'KATTINTÁSOS FELADAT';$('#scene-question-title').textContent=scene.oneWayTurn?'Szabályosan helyezkedett el az autó a balra kanyarodáshoz?':'Milyen sorrendben haladhatnak tovább?';$('#scene-question-copy').textContent=scene.oneWayTurn?'Figyeld meg, az úttest melyik oldalán helyezkedik el az autó az egyirányú úton, majd válassz.':'Kattints a szereplőkre az áthaladás teljes sorrendjében. A feladat csak az utolsó helyes választás után lesz sikeres.';$('.answer-editor').hidden=!!scene.oneWayTurn;$('.helper').innerHTML=scene.oneWayTurn?'<b>Egyirányú út – balra kanyarodás</b><br>Balra kanyarodás előtt az úttest bal oldalára kell húzódni.':'<b>Kattintásos sorrend</b><br>Minden helyes kattintás után válaszd ki a következő közlekedőt. Ha bármelyik lépésben rosszul döntesz, az érintett szereplők a saját útvonalukon elindulnak és a konfliktuspontban ütköznek.';updateNavigation();applyRotation();document.querySelectorAll('[data-scene]').forEach(b=>b.classList.toggle('active',+b.dataset.scene===n));const actors=collect(scene.initial,0),unique=[...new Map(actors.map(a=>[a.label,a])).values()];$('#legend').innerHTML=unique.map(a=>'<span><b style="border-color:'+palette[a.label]+';color:'+palette[a.label]+'">'+a.label+'</b>'+descriptions[a.kind]+'</span>').join('')+'<span class="directions">↗ Színes útvonalak: tervezett haladási irány</span>';reset()}
$('#grid').innerHTML=data.map((s,i)=>'<button data-scene="'+s.number+'" aria-label="'+(i+1)+'. feladat">'+String(i+1).padStart(3,'0')+'</button>').join('');document.querySelectorAll('[data-scene]').forEach(b=>b.onclick=()=>{if(practice.active)return;select(+b.dataset.scene);$('#library').classList.remove('open')});$('#collection').onclick=()=>{if(!practice.active)$('#library').classList.toggle('open')};$('#practice-start').onclick=startPractice;$('#practice-next').onclick=nextPractice;$('#search').oninput=filterGrid;$('#prev').onclick=()=>stepScene(-1);$('#next').onclick=()=>stepScene(1);$('#reset').onclick=()=>{if(!practice.active||!practice.answered)reset()};$('#solution').onclick=()=>choose(scene.correct,true);$('#play').onclick=()=>{if(frame>=total-1)frame=0;playing=!playing;last=0;draw()};$('#slow').onclick=e=>{slow=!slow;e.currentTarget.setAttribute('aria-pressed',slow);e.currentTarget.style.color=slow?'#f4cc63':''};$('#scrub').oninput=e=>{playing=false;frame=+e.target.value;draw()};$('#zoom').onclick=()=>$('#scene-shell').classList.add('zoomed');$('#close-zoom').onclick=()=>$('#scene-shell').classList.remove('zoomed');$('#modern').addEventListener('click',e=>{const actor=e.target.closest('[data-actor-label]');if(actor)clickActor(actor.dataset.actorLabel)});$('#modern').addEventListener('keydown',e=>{if(e.key!=='Enter'&&e.key!==' ')return;const actor=e.target.closest('[data-actor-label]');if(actor){e.preventDefault();clickActor(actor.dataset.actorLabel)}});document.addEventListener('keydown',e=>{if(e.key==='Escape')$('#scene-shell').classList.remove('zoomed')});

function randomQuestions(topic){const pool=data.filter(s=>topic==='all'||s.topic===topic).map(s=>s.number);for(let i=pool.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[pool[i],pool[j]]=[pool[j],pool[i]]}return pool.slice(0,10)}
function updatePracticePanel(){const panel=$('#practice-panel'),summary=$('#practice-summary'),next=$('#practice-next');panel.hidden=!practice.active&&!practice.finished;$('#collection').disabled=practice.active;document.querySelectorAll('[data-topic]').forEach(b=>b.disabled=practice.active);if(practice.finished){const percent=Math.round(practice.correct/practice.questions.length*100);summary.innerHTML='<span class="practice-result"><strong>'+practice.correct+'/'+practice.questions.length+'</strong> helyes válasz · '+percent+'%</span><span>Hibás: <strong>'+practice.wrong+'</strong></span>';next.hidden=false;next.textContent='Új gyakorlás'}else if(practice.active){summary.innerHTML='<span>Kérdés: <strong>'+(practice.index+1)+'/'+practice.questions.length+'</strong></span><span>Helyes: <strong>'+practice.correct+'</strong></span><span>Hibás: <strong>'+practice.wrong+'</strong></span>';next.hidden=!practice.answered;next.textContent=practice.index===practice.questions.length-1?'Eredmény megtekintése':'Következő kérdés →'}}
function startPractice(){practice.active=true;practice.finished=false;practice.topic=$('#practice-topic').value;practice.questions=randomQuestions(practice.topic);practice.index=0;practice.correct=0;practice.wrong=0;practice.answered=false;activeTopic=practice.topic;document.querySelectorAll('[data-topic]').forEach(b=>{b.classList.toggle('active',b.dataset.topic===activeTopic);b.setAttribute('aria-pressed',String(b.dataset.topic===activeTopic))});$('#practice-topic').disabled=true;$('#library').classList.remove('open');select(practice.questions[0]);updatePracticePanel()}
function nextPractice(){if(practice.finished){startPractice();return}if(!practice.active||!practice.answered)return;if(practice.index<practice.questions.length-1){practice.index++;practice.answered=false;select(practice.questions[practice.index]);updatePracticePanel();return}practice.active=false;practice.finished=true;playing=false;$('#practice-topic').disabled=false;$('#feedback').className='feedback good';$('#feedback').textContent='A 10 kérdéses gyakorlás véget ért. Az eredményed fent látható.';updateNavigation();updatePracticePanel()}

function filteredScenes(){const rank=new Map(sceneOrder.map((number,index)=>[number,index]));return data.filter(s=>activeTopic==='all'||s.topic===activeTopic).sort((a,b)=>rank.get(a.number)-rank.get(b.number))}
function filterGrid(){const query=$('#search').value.trim();document.querySelectorAll('[data-scene]').forEach(b=>{const s=data.find(item=>item.number===Number(b.dataset.scene));b.hidden=!s||(activeTopic!=='all'&&s.topic!==activeTopic)||!b.textContent.includes(query)});}
function updateNavigation(){const items=filteredScenes(),i=items.findIndex(s=>s.number===current);$('#prev').disabled=practice.active||i<=0;$('#next').disabled=practice.active||i<0||i>=items.length-1;const t=topics.find(t=>t[0]===activeTopic),isAll=activeTopic==='all';$('.library-head strong').textContent=isAll?t[1]:t[1]+' · '+items.length+' feladat';$('#topic-status').textContent=practice.active?'10 kérdéses gyakorlás':t[1]+(isAll?'': ' · '+items.length+' feladat')+(i>=0?' · '+(i+1)+'. a témakörben':'');}
function stepScene(delta){const items=filteredScenes(),i=items.findIndex(s=>s.number===current),next=items[i+delta];if(next)select(next.number)}
function pickTopic(id){if(practice.active)return;activeTopic=id;practice.finished=false;$('#practice-panel').hidden=true;document.querySelectorAll('[data-topic]').forEach(b=>{b.classList.toggle('active',b.dataset.topic===id);b.setAttribute('aria-pressed',String(b.dataset.topic===id))});$('#search').value='';filterGrid();select(filteredScenes()[0].number);}
function applyRotation(){$('#position').textContent=String(displayNumber(current)).padStart(3,'0');$('#modern').setAttribute('viewBox','0 0 590 590');$('#modern-drawing').setAttribute('transform','translate(560 0) rotate(90)')}
function updateCameraControls(){}
$('#topic-cards').innerHTML=topics.map(t=>'<button class="topic-card'+(t[0]==='all'?' active':'')+'" data-topic="'+t[0]+'" aria-pressed="'+(t[0]==='all')+'"><span class="topic-icon" aria-hidden="true">'+t[3]+'</span><span><strong>'+t[1]+'</strong><small>'+t[2]+'</small></span><span class="topic-count">'+(t[0]==='all'?data.length:data.filter(s=>s.topic===t[0]).length)+'</span></button>').join('');$('#practice-topic').innerHTML=topics.filter(t=>t[0]==='all'||data.filter(s=>s.topic===t[0]).length>=10).map(t=>'<option value="'+t[0]+'">'+t[1]+'</option>').join('');document.querySelectorAll('[data-topic]').forEach(b=>b.onclick=()=>pickTopic(b.dataset.topic));function tick(t){if(playing&&last){frame+=Math.min(t-last,80)/1000*scene.fps*(slow?.4:1);if(collisionMode&&frame>=collisionStopFrame){frame=collisionStopFrame;playing=false;collisionShown=collisionHappens;$('#feedback').className='feedback bad';$('#feedback').textContent=collisionHappens?'Ütközés! A járművek a tényleges útvonalukon, az útkereszteződésben találkoztak.':'Hibás válasz. A járművek a tényleges útvonalukon, ütközés nélkül haladtak tovább.'}else if(stageAnimating&&frame>=stagePauseFrame){frame=stagePauseFrame;playing=false;const departedLabels=stageMovingLabels.slice();stageFrozenState=stageStateAt(frame).filter(actor=>!departedLabels.includes(actor.label));stageAnimating=false;if(stageFinal)finishClickSequence();else if(queuedFinalStage.length){const automaticStage=queuedFinalStage.slice();queuedFinalStage=[];clickStages.push(automaticStage);renderClickAnswer();$('#feedback').className='feedback good';$('#feedback').textContent='Helyes! Az utolsó közlekedő automatikusan továbbhalad.';playCorrectStage(automaticStage,true)}else{awaitingStageChoice=true;$('#feedback').className='feedback good';$('#feedback').textContent='Helyes! Most kattints arra, aki a megmaradt szereplők közül következik.';controls()}}else if(frame>=total-1){frame=total-1;playing=false;if(pendingAutoAdvance)scheduleNextScene()}draw()}last=t;requestAnimationFrame(tick)}select(1);requestAnimationFrame(tick);
